sys_script_include.script:
var DateRangeUtils = Class.create();
/*DateRangeUtils.prototype = {
    initialize: function() {
    },*/
DateRangeUtils.prototype =  Object.extendsObject(global.AbstractAjaxProcessor,{
    getDateRanges: function() {
        // 获取日期范围
        var beginToday = gs.beginningOfToday();
        var endToday = gs.endOfToday();
        var beginTomorrow = gs.beginningOfTomorrow();
        var endTomorrow = gs.endOfTomorrow();
        var beginYesterday = gs.beginningOfYesterday();
        var endYesterday = gs.endOfYesterday();

        // 计算时间差
        var gdt1 = new GlideDateTime(beginToday);
        var gdt2 = new GlideDateTime(beginTomorrow);
        var durTomorrow = GlideDateTime.subtract(gdt2, gdt1).getDisplayValue();

        var gdt3 = new GlideDateTime(endToday);
        var gdt4 = new GlideDateTime(endTomorrow);
        var durEndTomorrow = GlideDateTime.subtract(gdt4, gdt3).getDisplayValue();

        var gdt5 = new GlideDateTime(beginToday);
        var gdt6 = new GlideDateTime(beginYesterday);
        var durYesterday = GlideDateTime.subtract(gdt6, gdt5).getDisplayValue();

        var gdt7 = new GlideDateTime(endToday);
        var gdt8 = new GlideDateTime(endYesterday);
        var durEndYesterday = GlideDateTime.subtract(gdt8, gdt7).getDisplayValue();

        // 返回结果
        return JSON.stringify({
            beginningOfToday: beginToday,
            endOfToday: endToday,
            beginTomorrow: beginTomorrow,
            endTomorrow: endTomorrow,
            beginYesterday: beginYesterday,
            endYesterday: endYesterday,
            durationTomorrow: durTomorrow,
            durationEndTomorrow: durEndTomorrow,
            durationYesterday: durYesterday,
            durationEndYesterday: durEndYesterday
        });
    },



    type: 'DateRangeUtils'
});	
//};
